# Standalone deterministic verifier. No imports, no I/O, no floats.
# Entry point: verify(witness) raises on any failed check, returns True on PASS.

def verify(witness):
    V = list(witness["vertex_labels"])
    if sorted(V) != ['a', 'b', 'c', 'd', 'u', 'v']:
        raise ValueError("FAIL: vertex set mismatch")
    E = set()
    for e in witness["edge_list"]:
        x, y = e[0], e[1]
        if x == y or x not in V or y not in V:
            raise ValueError("FAIL: malformed edge")
        E.add(frozenset((x, y)))
    if len(E) != len(witness["edge_list"]):
        raise ValueError("FAIL: duplicate edge")

    def adj(x, y):
        return x != y and frozenset((x, y)) in E

    p0 = witness["nonadjacent_pair"][0]
    p1 = witness["nonadjacent_pair"][1]
    if sorted(witness["nonadjacent_pair"]) != ['u', 'v']:
        raise ValueError("FAIL: wrong pair named")

    # Check 1: u and v are nonadjacent.
    if adj(p0, p1):
        raise ValueError("FAIL: named pair is adjacent")

    # Check 2: common neighborhood of u and v is exactly {a,b,c,d} and induces
    # a K_22 with parts {a,b} and {c,d} (all four cross edges present).
    cn = []
    for x in V:
        if adj('u', x) and adj('v', x):
            cn.append(x)
    if sorted(cn) != ['a', 'b', 'c', 'd']:
        raise ValueError("FAIL: common neighborhood mismatch")
    for x in ['a', 'b']:
        for y in ['c', 'd']:
            if not adj(x, y):
                raise ValueError("FAIL: missing K_22 cross edge")

    # Check 3: G is K_222-free. Enumerate all perfect matchings of the vertex
    # set into three unordered pairs by recursion; each triple of parts must
    # miss at least one cross edge.
    matchings = []

    def enum(remaining, current):
        if len(remaining) == 0:
            matchings.append(list(current))
            return
        first = remaining[0]
        for i in range(1, len(remaining)):
            partner = remaining[i]
            rest = [x for j, x in enumerate(remaining) if j != 0 and j != i]
            current.append(frozenset((first, partner)))
            enum(rest, current)
            current.pop()

    enum(V, [])
    if len(matchings) != 15:
        raise ValueError("FAIL: expected 15 perfect matchings")
    for m in matchings:
        complete = True
        for i in range(3):
            for j in range(i + 1, 3):
                for x in m[i]:
                    for y in m[j]:
                        if not adj(x, y):
                            complete = False
        if complete:
            raise ValueError("FAIL: graph contains a K_222")

    return True  # PASS: counterexample to L1 verified exactly

verify({
 "vertex_labels": ["u", "v", "a", "b", "c", "d"],
 "edge_list": [["u","a"],["u","b"],["u","c"],["u","d"],
               ["v","a"],["v","b"],["v","c"],["v","d"],
               ["a","c"],["a","d"],["b","c"],["b","d"]],
 "nonadjacent_pair": ["u", "v"]
})
